/** Base URL of the optional live backend. Empty string = same origin (Vite dev proxy). */
export const API_BASE_URL: string = (import.meta.env?.VITE_API_BASE_URL as string | undefined)?.replace(/\/+$/, '') || '';

/** Where the precomputed static demo JSON lives (generated by scripts/export_static_demo.py). */
export const DEMO_DATA_BASE: string = `${import.meta.env?.BASE_URL ?? '/'}demo-data`;
